card:{name:'Карточка проекта',html:'<main class="page">\n  <article class="card">\n    <span class="badge">МОЙ ПЕРВЫЙ ПРОЕКТ</span>\n    <h1>Привет, веб 👋</h1>\n    <p>Я учусь создавать сайты. Эта карточка — начало большого пути.</p>\n    <button id="hello">Попробовать JavaScript →</button>\n    <p id="result" role="status"></p>\n  </article>\n</main>',css:'* { box-sizing: border-box; }\nbody { margin: 0; font-family: system-ui, sans-serif; color: #252333; }\n.page { min-height: 100vh; display: grid; place-items: center; padding: 24px; background: #f3effc; }\n.card { width: min(100%, 360px); padding: 32px; border-radius: 20px; background: white; box-shadow: 0 15px 45px #7557df12; }\n.badge { font-size: 10px; color: #7557df; letter-spacing: 1px; }\nh1 { font-size: 32px; letter-spacing: -1px; }\np { color: #85808e; line-height: 1.7; }\nbutton { border: 0; padding: 13px 18px; border-radius: 8px; background: #7557df; color: white; cursor: pointer; }\nbutton:focus-visible { outline: 3px solid #b59df8; outline-offset: 3px; }',js:"let clicks = 0;\ndocument.querySelector('#hello').addEventListener('click', () => {\n  clicks += 1;\n  document.querySelector('#result').textContent = `Шагов к своему сайту: ${clicks}!`;\n  console.log('Кнопка нажата', clicks);\n});"},
grid:{name:'Сетка Flexbox и Grid',html:'<main><h1>Мои проекты</h1><div class="cards"><article>Сайт-портфолио</article><article>Telegram-бот</article><article>Игровое сообщество</article></div></main>',css:'* { box-sizing: border-box; }\nbody { margin: 0; font: 16px/1.6 system-ui; background: #f7f8fa; color: #262431; }\nmain { padding: 28px; }\nh1 { font-size: 26px; }\n.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(180px, 100%), 1fr)); gap: 16px; }\narticle { min-height: 140px; padding: 24px; display: flex; align-items: end; border: 1px solid #e0d8f4; border-radius: 14px; background: #eee7fc; color: #7557df; }',js:"console.log('Попробуй изменить gap и minmax в CSS.');"},
